final class Print_Options_WC {
 const META='_pov_groups', SETTINGS='_pov_settings', VERSION=POV_VERSION;
 private $quote_printed=[];
 function __construct(){
  add_action('admin_menu',[$this,'appearance_menu']); add_action('admin_post_pov_save_template',[$this,'save_template']); add_action('admin_post_pov_bulk_apply',[$this,'bulk_apply']); add_filter('woocommerce_product_export_column_names',[$this,'csv_columns']); add_filter('woocommerce_product_export_product_default_columns',[$this,'csv_columns']); add_filter('woocommerce_product_export_product_column_pov_settings',[$this,'export_settings'],10,2); add_filter('woocommerce_product_export_product_column_pov_groups',[$this,'export_groups'],10,2); add_filter('woocommerce_csv_product_import_mapping_options',[$this,'csv_columns']); add_filter('woocommerce_csv_product_import_mapping_default_columns',[$this,'csv_mapping']); add_filter('woocommerce_product_import_pre_insert_product_object',[$this,'import_product'],10,2);  add_action('admin_init',[$this,'appearance_register']);
  add_action('add_meta_boxes',[$this,'boxes']); add_action('save_post_product',[$this,'save']); add_action('admin_enqueue_scripts',[$this,'admin_assets']);
  add_action('woocommerce_before_add_to_cart_button',[$this,'render'],12); add_filter('woocommerce_quantity_input_args',[$this,'quantity_args'],20,2); add_action('woocommerce_after_add_to_cart_form',[$this,'quote_button'],20); add_action('woocommerce_single_product_summary',[$this,'quote_button'],35); add_shortcode('pov_quote_button',[$this,'quote_shortcode']); add_filter('the_content',[$this,'quote_content_fallback'],20);
  add_filter('woocommerce_add_to_cart_validation',[$this,'validate'],10,5); add_filter('woocommerce_update_cart_validation',[$this,'cart_qty_validation'],10,4);
  add_filter('woocommerce_add_cart_item_data',[$this,'cart_data'],10,3); add_filter('woocommerce_get_item_data',[$this,'item_data'],10,2);
  add_action('woocommerce_before_calculate_totals',[$this,'price'],100); add_action('woocommerce_checkout_create_order_line_item',[$this,'order_item'],10,4);
  add_action('wp_enqueue_scripts',[$this,'frontend_assets']); add_filter('woocommerce_cart_item_name',[$this,'cart_item_name'],10,3);
 }

 // Dedicated WooCommerce CSV columns: JSON is portable and survives an export/import round trip.
 function csv_columns($columns){$columns['pov_settings']='Print Options - Settings (JSON)';$columns['pov_groups']='Print Options - Groups (JSON)';return $columns;}
 function csv_mapping($columns){$columns['Print Options - Settings (JSON)']='pov_settings';$columns['Print Options - Groups (JSON)']='pov_groups';return $columns;}
 function export_settings($value,$product){return wp_json_encode($this->settings($product->get_id()),JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);}
 function export_groups($value,$product){return wp_json_encode($this->groups($product->get_id()),JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);}
 function import_product($product,$data){
  foreach(['pov_settings'=>self::SETTINGS,'pov_groups'=>self::META] as $field=>$key){
   if(!array_key_exists($field,$data))continue;
   $raw=$data[$field]; if(!is_string($raw))continue;
   $decoded=json_decode($raw,true);if(!is_array($decoded))continue;
   if($field==='pov_settings'){
    $decoded=wp_parse_args($decoded,['min'=>1,'step'=>1,'mode'=>'fixed','tiers'=>'','artwork'=>0,'design_fee'=>0,'upload_required'=>1,'templates_pdf'=>'','templates_eps'=>'','quote'=>0]);
    $decoded['min']=max(1,absint($decoded['min']));$decoded['step']=max(1,absint($decoded['step']));
    $decoded['mode']=$decoded['mode']==='dynamic'?'dynamic':'fixed';
    $decoded['tiers']=sanitize_textarea_field($decoded['tiers']);
    $decoded['artwork']=empty($decoded['artwork'])?0:1;$decoded['quote']=empty($decoded['quote'])?0:1;$decoded['upload_required']=empty($decoded['upload_required'])?0:1;
    $decoded['design_fee']=max(0,(float)$decoded['design_fee']);
    foreach(['templates_pdf','templates_eps'] as $url)$decoded[$url]=esc_url_raw($decoded[$url]);
   }else{
    $clean=[];foreach(array_slice($decoded,0,30) as $g){if(!is_array($g))continue;
     $title=sanitize_text_field($g['title']??'');if(!$title)continue;$opts=[];
     foreach(array_slice(is_array($g['options']??null)?$g['options']:[],0,100) as $o){if(!is_array($o))continue;$label=sanitize_text_field($o['label']??'');if(!$label)continue;$opts[]=['label'=>$label,'price'=>max(0,(float)($o['price']??0)),'charge'=>($o['charge']??'unit')==='order'?'order':'unit','image'=>esc_url_raw($o['image']??'')];}
     if($opts)$clean[]=['title'=>$title,'required'=>!empty($g['required']),'multiple'=>!empty($g['multiple']),'options'=>$opts];
    }$decoded=$clean;
   }
   $product->update_meta_data($key,$decoded);
  }return $product;
 }

 function template_store(){ $v=get_option('pov_templates',[]);return is_array($v)?$v:[]; }
 function save_template(){
  if(!current_user_can('manage_woocommerce'))wp_die('Acces interzis.');check_admin_referer('pov_save_template');
  $id=absint($_POST['source_product']??0);$product=wc_get_product($id);
  if(!$product||!$product->is_type('simple'))wp_die('Alege un produs simplu valid.');
  $name=sanitize_text_field(wp_unslash($_POST['template_name']??''));if(!$name)wp_die('Introdu un nume.');
  $all=$this->template_store();$key=wp_generate_uuid4();$all[$key]=['name'=>$name,'settings'=>$this->settings($id),'groups'=>$this->groups($id)];update_option('pov_templates',$all,false);
  wp_safe_redirect(add_query_arg(['page'=>'pov-bulk','pov_notice'=>'template'],admin_url('admin.php')));exit;
 }
 function bulk_apply(){
  if(!current_user_can('manage_woocommerce'))wp_die('Acces interzis.');check_admin_referer('pov_bulk_apply');
  $ids=array_unique(array_filter(array_map('absint',(array)($_POST['product_ids']??[]))));if(!$ids)wp_die('Selectează cel puțin un produs.');
  $action=sanitize_key($_POST['bulk_action']??'');$templates=$this->template_store();$key=sanitize_text_field(wp_unslash($_POST['template_key']??''));
  if($action==='template'&&!isset($templates[$key]))wp_die('Șablon invalid.');
  if(!in_array($action,['template','quantity','unit_price'],true))wp_die('Acțiune invalidă.');
  $min=max(1,absint($_POST['bulk_min']??1));$step=max(1,absint($_POST['bulk_step']??1));
  $group_name=sanitize_text_field(wp_unslash($_POST['bulk_group']??''));$option_name=sanitize_text_field(wp_unslash($_POST['bulk_option']??''));
  $new_price=max(0,(float)str_replace(',','.',sanitize_text_field(wp_unslash($_POST['bulk_price']??'0'))));
  if($action==='unit_price'&&(!$group_name||!$option_name))wp_die('Completează numele grupului și al opțiunii.');
  $count=0;foreach(array_slice($ids,0,200) as $id){if(!current_user_can('edit_post',$id))continue;$product=wc_get_product($id);if(!$product||!$product->is_type('simple'))continue;
   if($action==='template'){update_post_meta($id,self::SETTINGS,$templates[$key]['settings']);update_post_meta($id,self::META,$templates[$key]['groups']);}
   elseif($action==='quantity'){$s=$this->settings($id);$s['min']=$min;$s['step']=$step;update_post_meta($id,self::SETTINGS,$s);}
   else{$groups=$this->groups($id);$changed=false;foreach($groups as &$g){if($g['title']!==$group_name)continue;foreach($g['options'] as &$o){if($o['label']===$option_name){$o['price']=$new_price;$changed=true;}}unset($o);}unset($g);if(!$changed)continue;update_post_meta($id,self::META,$groups);}
   wc_delete_product_transients($id);$count++;
  }
  wp_safe_redirect(add_query_arg(['page'=>'pov-bulk','pov_notice'=>'applied','pov_count'=>$count],admin_url('admin.php')));exit;
 }
 function bulk_page(){
  if(!current_user_can('manage_woocommerce'))return;
  $products=wc_get_products(['type'=>'simple','status'=>['publish','draft','private'],'limit'=>200,'orderby'=>'title','order'=>'ASC']);$templates=$this->template_store();
  echo '<div class="wrap pov-bulk-page"><h1>Print Options Studio — Șabloane și editare în masă</h1><p>Șabloanele sunt copii independente ale configurației produsului sursă. Aplicarea unui șablon înlocuiește toate grupurile și setările Print Options ale produselor selectate.</p>';
  if(isset($_GET['pov_notice']))echo '<div class="notice notice-success"><p>'.(sanitize_key($_GET['pov_notice'])==='template'?'Șablonul a fost salvat.':'Produse actualizate: '.absint($_GET['pov_count']??0)).'</p></div>';
  echo '<div class="pov-bulk-panels"><section class="pov-bulk-card"><h2>1. Salvează un șablon reutilizabil</h2><form method="post" action="'.esc_url(admin_url('admin-post.php')).'">';wp_nonce_field('pov_save_template');echo '<input type="hidden" name="action" value="pov_save_template"><p><label>Nume șablon<br><input required class="regular-text" name="template_name" placeholder="Ex.: Cărți de vizită standard"></label></p><p><label>Produs sursă<br><select name="source_product" required><option value="">Alege produsul</option>';
  foreach($products as $p)echo '<option value="'.(int)$p->get_id().'">'.esc_html($p->get_name().' (#'.$p->get_id().')').'</option>';
  echo '</select></label></p><button class="button button-primary">Salvează șablon</button></form></section><section class="pov-bulk-card"><h2>2. Aplică modificări produselor</h2><form method="post" action="'.esc_url(admin_url('admin-post.php')).'">';wp_nonce_field('pov_bulk_apply');echo '<input type="hidden" name="action" value="pov_bulk_apply"><p><label>Operație<br><select name="bulk_action" id="pov-bulk-action"><option value="template">Aplică șablon complet</option><option value="quantity">Modifică minimul și pasul</option><option value="unit_price">Modifică prețul unei opțiuni existente</option></select></label></p><div data-bulk="template"><label>Șablon<br><select name="template_key"><option value="">Alege șablonul</option>';
  foreach($templates as $key=>$t)echo '<option value="'.esc_attr($key).'">'.esc_html($t['name']).'</option>';
  echo '</select></label></div><div data-bulk="quantity" hidden><label>Minim <input type="number" name="bulk_min" min="1" value="100"></label> <label>Pas <input type="number" name="bulk_step" min="1" value="100"></label></div><div data-bulk="unit_price" hidden><p><label>Grup (nume exact) <input name="bulk_group" placeholder="Plastifiere"></label></p><p><label>Opțiune (nume exact) <input name="bulk_option" placeholder="Mată"></label></p><label>Preț nou <input type="number" step="0.01" min="0" name="bulk_price" value="0"></label></div>';
  echo '<h3>Selectează produsele (maximum 200)</h3><p><label><input type="checkbox" id="pov-select-all"> Selectează toate produsele afișate</label></p><div class="pov-bulk-products">';foreach($products as $p)echo '<label><input type="checkbox" name="product_ids[]" value="'.(int)$p->get_id().'"> '.esc_html($p->get_name()).' <small>#'.(int)$p->get_id().'</small></label>';echo '</div><p><strong>Atenție:</strong> fă un backup înainte de aplicarea în masă. Operația modifică datele produselor imediat.</p><button type="submit" class="button button-primary">Aplică produselor selectate</button></form></section></div><script>document.addEventListener("DOMContentLoaded",function(){const s=document.getElementById("pov-bulk-action");if(!s)return;function toggle(){document.querySelectorAll("[data-bulk]").forEach(x=>x.hidden=x.dataset.bulk!==s.value)}s.addEventListener("change",toggle);toggle();document.getElementById("pov-select-all").addEventListener("change",function(){document.querySelectorAll(".pov-bulk-products input").forEach(x=>x.checked=this.checked)})});</script><style>.pov-bulk-panels{display:grid;grid-template-columns:1fr 1.5fr;gap:20px;max-width:1250px}.pov-bulk-card{background:#fff;border:1px solid #d9e0e8;border-radius:14px;padding:24px;box-shadow:0 3px 14px #152a4010}.pov-bulk-card input:not([type=checkbox]),.pov-bulk-card select{max-width:100%;margin-top:5px}.pov-bulk-products{display:grid;grid-template-columns:1fr 1fr;gap:8px;max-height:360px;overflow:auto;padding:12px;border:1px solid #ddd;border-radius:8px}.pov-bulk-products label{padding:5px}.pov-bulk-products small{color:#667085}@media(max-width:900px){.pov-bulk-panels,.pov-bulk-products{grid-template-columns:1fr}}</style></div>';
 }
 function appearance_defaults(){return ['background'=>'#ffffff','text'=>'#344054','accent'=>'#f47735','radius'=>18,'shadow'=>1,'position'=>'bottom','label'=>'Preț total','font_size'=>22,'bottom'=>22,'mobile_bottom'=>100,'width'=>340];}
 function appearance(){return wp_parse_args((array)get_option('pov_bubble_appearance',[]),$this->appearance_defaults());}
 function appearance_register(){register_setting('pov_bubble_group','pov_bubble_appearance',['type'=>'array','sanitize_callback'=>[$this,'sanitize_appearance']]);}
 function sanitize_appearance($raw){$d=$this->appearance_defaults();$raw=is_array($raw)?$raw:[];$v=[];foreach(['background','text','accent'] as $k)$v[$k]=sanitize_hex_color($raw[$k]??'')?:$d[$k];foreach(['radius'=>[0,40],'font_size'=>[14,34],'bottom'=>[0,400],'mobile_bottom'=>[0,400],'width'=>[220,600]] as $k=>$range)$v[$k]=min($range[1],max($range[0],absint($raw[$k]??$d[$k])));$v['shadow']=empty($raw['shadow'])?0:1;$v['position']=in_array($raw['position']??'',['bottom','bottom-left','bottom-right'],true)?$raw['position']:'bottom';$v['label']=sanitize_text_field($raw['label']??$d['label']);return $v;}
 function appearance_menu(){add_submenu_page('woocommerce','Aspect preț flotant','Aspect preț flotant','manage_woocommerce','pov-appearance',[$this,'appearance_page']);add_submenu_page('woocommerce','Șabloane și editare în masă','Șabloane și editare în masă','manage_woocommerce','pov-bulk',[$this,'bulk_page']);}
 function appearance_page(){if(!current_user_can('manage_woocommerce'))return;$a=$this->appearance();echo '<div class="wrap"><h1>Print Options — aspect preț flotant</h1><p>Personalizează bula de preț afișată pe paginile produselor configurabile. Modificările sunt globale.</p><form method="post" action="options.php">';settings_fields('pov_bubble_group');echo '<table class="form-table"><tbody>';foreach(['background'=>'Fundal','text'=>'Culoare text','accent'=>'Culoare accent'] as $k=>$label)echo '<tr><th>'.esc_html($label).'</th><td><input type="color" name="pov_bubble_appearance['.esc_attr($k).']" value="'.esc_attr($a[$k]).'"></td></tr>';foreach(['radius'=>'Rotunjire colțuri (px)','font_size'=>'Dimensiune preț (px)','bottom'=>'Distanță jos — desktop (px)','mobile_bottom'=>'Distanță jos — mobil (px)','width'=>'Lățime maximă (px)'] as $k=>$label)echo '<tr><th>'.esc_html($label).'</th><td><input type="number" min="0" name="pov_bubble_appearance['.esc_attr($k).']" value="'.esc_attr($a[$k]).'"></td></tr>';echo '<tr><th>Text etichetă</th><td><input type="text" name="pov_bubble_appearance[label]" value="'.esc_attr($a['label']).'"></td></tr><tr><th>Poziție</th><td><select name="pov_bubble_appearance[position]">';foreach(['bottom'=>'Jos, centru','bottom-left'=>'Jos, stânga','bottom-right'=>'Jos, dreapta'] as $k=>$label)echo '<option value="'.esc_attr($k).'" '.selected($a['position'],$k,false).'>'.esc_html($label).'</option>';echo '</select></td></tr><tr><th>Umbră</th><td><label><input type="checkbox" name="pov_bubble_appearance[shadow]" value="1" '.checked($a['shadow'],1,false).'> Activată</label></td></tr></tbody></table>';submit_button('Salvează aspectul');echo '</form></div>';}
 function settings($id){$s=get_post_meta($id,self::SETTINGS,true);return wp_parse_args(is_array($s)?$s:[],['min'=>1,'step'=>1,'mode'=>'fixed','tiers'=>'','artwork'=>0,'design_fee'=>0,'templates_pdf'=>'','templates_eps'=>'','upload_required'=>1,'quote'=>0]);}
 function groups($id){$g=get_post_meta($id,self::META,true);return is_array($g)?$g:[];}
 function boxes(){add_meta_box('pov_options','Opțiuni vizuale produs',[$this,'box_html'],'product','normal','default');}
 function box_html($post){$s=$this->settings($post->ID);wp_nonce_field('pov_save','pov_nonce');echo '<div class="pov-admin-settings"><h3>Cantitate și calcul preț</h3><p><label>Cantitate minimă <input type="number" min="1" step="1" name="pov_min" value="'.esc_attr($s['min']).'"></label> &nbsp; <label>Multiplicator / pas <input type="number" min="1" step="1" name="pov_step" value="'.esc_attr($s['step']).'"></label></p><p class="description">Exemplu: minim 100, pas 100 permite 100, 200, 300 ... bucăți. În coș se aplică aceeași regulă.</p><p><label>Mod preț <select name="pov_mode"><option value="fixed" '.selected($s['mode'],'fixed',false).'>A — Suplimente fixe per unitate</option><option value="dynamic" '.selected($s['mode'],'dynamic',false).'>B — Preț dinamic după cantitate</option></select></label></p><p><label><strong>Grilă prețuri cantitative (mod B)</strong><br><textarea name="pov_tiers" rows="5" style="width:100%;max-width:520px" placeholder="100=50&#10;200=90&#10;500=190">'.esc_textarea($s['tiers']).'</textarea></label></p><p class="description">Un rând per prag: CANTITATE=PREȚ TOTAL de bază (fără opțiuni). Pentru o cantitate între praguri se folosește prețul unitar al celui mai mare prag atins. Sub primul prag se folosește prețul WooCommerce. Prețurile introduse sunt în aceeași bază fiscală ca prețul produsului WooCommerce. Dacă nu există grilă, se folosește prețul WooCommerce.</p><p class="description">În mod A: preț produs WooCommerce × cantitate + suplimente per unitate × cantitate + suplimente per comandă. În mod B: grilă cantitativă + suplimente per unitate × cantitate + suplimente per comandă.</p><hr><h3>Grafică și template-uri</h3><p><label><input type="checkbox" name="pov_artwork" value="1" '.checked(!empty($s['artwork']),true,false).'> Activează secțiunea Grafică</label></p><p><label>Cost design realizat de noi (per comandă) <input type="number" min="0" step="0.01" name="pov_design_fee" value="'.esc_attr($s['design_fee']).'"></label></p><p><label><input type="checkbox" name="pov_upload_required" value="1" '.checked(!empty($s['upload_required']),true,false).'> Fișier obligatoriu pentru «Cu design propriu»</label></p><p><label>Template PDF (URL Media Library) <input class="widefat" type="url" name="pov_templates_pdf" value="'.esc_attr($s['templates_pdf']).'"></label></p><p><label>Template EPS (URL Media Library) <input class="widefat" type="url" name="pov_templates_eps" value="'.esc_attr($s['templates_eps']).'"></label></p><p class="description">Încarcă fișierele în Media Library și copiază URL-ul. Dacă WordPress blochează EPS, încarcă-l prin SFTP în uploads și inserează URL-ul public.</p><h3>Cerere ofertă</h3><p><label><input type="checkbox" name="pov_quote" value="1" '.checked(!empty($s['quote']),true,false).'> Afișare buton „Cere ofertă”</label></p><p class="description">Butonul apare sub butonul „Adaugă în coș” și deschide pagina <a href="'.esc_url(POV_Quote::page_url()).'" target="_blank" rel="noopener">Cere ofertă</a>, cu produsul completat automat în formular. Dacă tema nu afișează butonul (de exemplu la produse fără preț), poți plasa manual shortcode-ul <code>[pov_quote_button]</code> în descrierea produsului.</p></div><hr><h3>Grupuri de opțiuni</h3><p>Opțiunile sunt afișate ca carduri. Poți seta un supliment per unitate sau per comandă. Se aplică produselor simple.</p><div id="pov-admin-groups">';foreach($this->groups($post->ID) as $g)$this->admin_group($g);echo '</div><button type="button" class="button" id="pov-add-group">+ Adaugă grup</button><script type="text/template" id="pov-group-template">';$this->admin_group(['title'=>'','required'=>true,'multiple'=>false,'options'=>[]]);echo '</script><script type="text/template" id="pov-option-template">';$this->admin_option([]);echo '</script>';}
 function admin_group($g){echo '<div class="pov-admin-group"><div class="pov-admin-head"><strong>Grup</strong> <button type="button" class="button-link-delete pov-remove-group">Șterge grup</button></div><p><label>Titlu <input class="widefat pov-group-title" value="'.esc_attr($g['title']??'').'"></label></p><p><label><input type="checkbox" class="pov-required" '.checked(!empty($g['required']),true,false).'> Obligatoriu</label> &nbsp; <label><input type="checkbox" class="pov-multiple" '.checked(!empty($g['multiple']),true,false).'> Selecție multiplă</label></p><div class="pov-admin-options">';foreach(($g['options']??[]) as $o)$this->admin_option($o);echo '</div><button type="button" class="button pov-add-option">+ Adaugă opțiune</button></div>';}
 function admin_option($o){echo '<div class="pov-admin-option"><input class="pov-label" placeholder="Denumire" value="'.esc_attr($o['label']??'').'"><input type="number" step="0.01" min="0" class="pov-price" placeholder="Supliment" value="'.esc_attr($o['price']??0).'"><select class="pov-charge"><option value="unit" '.selected($o['charge']??'unit','unit',false).'>/ unitate</option><option value="order" '.selected($o['charge']??'unit','order',false).'>/ comandă</option></select><input class="pov-image" placeholder="URL imagine (opțional)" value="'.esc_attr($o['image']??'').'"><button type="button" class="button pov-media">Imagine</button><button type="button" class="button-link-delete pov-remove-option">×</button></div>';}
 function admin_assets($hook){global $post;if(!in_array($hook,['post.php','post-new.php'],true)||!$post||$post->post_type!=='product')return;wp_enqueue_media();wp_enqueue_script('pov-admin',plugins_url('assets/admin.js',__FILE__),['jquery'],self::VERSION,true);wp_enqueue_style('pov-admin',plugins_url('assets/admin.css',__FILE__),[],self::VERSION);}
 function save($id){if(!isset($_POST['pov_nonce'])||!wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['pov_nonce'])),'pov_save')||!current_user_can('edit_post',$id)||(defined('DOING_AUTOSAVE')&&DOING_AUTOSAVE))return;
 $min=max(1,absint($_POST['pov_min']??1));$step=max(1,absint($_POST['pov_step']??1));$mode=($_POST['pov_mode']??'fixed')==='dynamic'?'dynamic':'fixed';$tiers_text=sanitize_textarea_field(wp_unslash($_POST['pov_tiers']??''));$tiers=[];foreach(preg_split('/\r?\n/',$tiers_text) as $line){if(preg_match('/^\s*(\d+)\s*=\s*(\d+(?:[.,]\d{1,4})?)\s*$/',$line,$m)&& (int)$m[1]>0)$tiers[(int)$m[1]]=max(0,(float)str_replace(',','.',$m[2]));}ksort($tiers,SORT_NUMERIC);$lines=[];foreach($tiers as $q=>$v)$lines[]=$q.'='.$v;update_post_meta($id,self::SETTINGS,['min'=>$min,'step'=>$step,'mode'=>$mode,'tiers'=>implode("\n",$lines),'artwork'=>!empty($_POST['pov_artwork'])?1:0,'design_fee'=>max(0,(float)($_POST['pov_design_fee']??0)),'upload_required'=>!empty($_POST['pov_upload_required'])?1:0,'templates_pdf'=>esc_url_raw(wp_unslash($_POST['pov_templates_pdf']??'')),'templates_eps'=>esc_url_raw(wp_unslash($_POST['pov_templates_eps']??'')),'quote'=>!empty($_POST['pov_quote'])?1:0]);
 if(!isset($_POST['pov_json']))return;$raw=json_decode(wp_unslash($_POST['pov_json']),true);if(!is_array($raw))return;$clean=[];foreach(array_slice($raw,0,30) as $g){if(!is_array($g))continue;$title=sanitize_text_field($g['title']??'');if(!$title)continue;$opts=[];foreach(array_slice(is_array($g['options']??null)?$g['options']:[],0,100) as $o){if(!is_array($o))continue;$label=sanitize_text_field($o['label']??'');if(!$label)continue;$opts[]=['label'=>$label,'price'=>max(0,(float)($o['price']??0)),'charge'=>($o['charge']??'unit')==='order'?'order':'unit','image'=>esc_url_raw($o['image']??'')];}if($opts)$clean[]=['title'=>$title,'required'=>!empty($g['required']),'multiple'=>!empty($g['multiple']),'options'=>$opts];}update_post_meta($id,self::META,$clean);}
 function valid_qty($id,$qty){$s=$this->settings($id);return is_numeric($qty)&& (int)$qty==$qty && (int)$qty >=$s['min']&&((int)$qty-$s['min'])%$s['step']===0;}
 function quantity_args($args,$product){if(!$product||!$product->is_type('simple'))return $args;$s=$this->settings($product->get_id());if($s['min']===1&&$s['step']===1)return $args;$args['min_value']=max((int)($args['min_value']??1),$s['min']);$args['step']=$s['step'];$args['input_value']=max($s['min'],(int)($args['input_value']??1));if(($args['input_value']-$s['min'])%$s['step'])$args['input_value']=$s['min'];return $args;}
 function render(){global $product;if(!$product||!$product->is_type('simple'))return;$groups=$this->groups($product->get_id());$s=$this->settings($product->get_id());if(!$groups&&$s['mode']==='fixed'&&!$s['artwork']&&$s['min']===1&&$s['step']===1)return;$tiers=$this->parse_tiers($s['tiers']);echo '<div class="pov-configurator" data-mode="'.esc_attr($s['mode']).'" data-tiers="'.esc_attr(wp_json_encode($tiers)).'" data-base="'.esc_attr((float)$product->get_price()).'" data-min="'.esc_attr($s['min']).'" data-step="'.esc_attr($s['step']).'" data-design-fee="'.esc_attr($s['design_fee']).'" data-tax-rate="'.esc_attr($this->preview_tax_rate($product)).'" data-prices-tax-included="'.(wc_prices_include_tax()?'1':'0').'">';foreach($groups as $i=>$g){$type=!empty($g['multiple'])?'checkbox':'radio';echo '<fieldset class="pov-group"><legend>'.esc_html($g['title']).(!empty($g['required'])?' <span class="pov-star">*</span>':'').'</legend><div class="pov-grid">';foreach($g['options'] as $j=>$o){$name='pov['.$i.']'.($type==='checkbox'?'[]':'');$id='pov-'.$product->get_id().'-'.$i.'-'.$j;echo '<label class="pov-card" for="'.esc_attr($id).'"><input type="'.$type.'" name="'.esc_attr($name).'" id="'.esc_attr($id).'" value="'.esc_attr($j).'" data-price="'.esc_attr($o['price']).'" data-charge="'.esc_attr($o['charge']??'unit').'" '.(($type==='radio'&&$j===0)?'checked':'').'><span class="pov-card-inner">';if(!empty($o['image']))echo '<img src="'.esc_url($o['image']).'" alt="" loading="lazy">';echo '<span class="pov-card-text"><span class="pov-card-label">'.esc_html($o['label']).'</span>';if((float)$o['price']>0)echo '<small>+'.wc_price($o['price']).' '.(($o['charge']??'unit')==='order'?'/ comandă':'/ buc.').'</small>';echo '</span><span class="pov-check">✓</span></span></label>';}echo '</div></fieldset>';}if(!empty($s['artwork'])){$this->artwork_render($s);} echo '</div>';$a=$this->appearance();echo '<div class="pov-price-bubble pov-position-'.esc_attr($a['position']).'" role="status" aria-live="polite" style="--pov-bubble-bg:'.esc_attr($a['background']).';--pov-bubble-text:'.esc_attr($a['text']).';--pov-bubble-accent:'.esc_attr($a['accent']).';--pov-bubble-radius:'.(int)$a['radius'].'px;--pov-bubble-size:'.(int)$a['font_size'].'px;--pov-bubble-bottom:'.(int)$a['bottom'].'px;--pov-bubble-mobile-bottom:'.(int)$a['mobile_bottom'].'px;--pov-bubble-width:'.(int)$a['width'].'px" data-shadow="'.(int)$a['shadow'].'"><div class="pov-bubble-lines"><div><span>Preț / buc.</span><strong class="pov-bubble-unit">—</strong></div><div><span>Cantitate</span><strong class="pov-bubble-qty">—</strong></div><div class="pov-bubble-total-row"><span>'.esc_html($a['label']).'</span><strong class="pov-bubble-price">—</strong></div></div></div>';}

 function preview_tax_rate($product){if(!wc_tax_enabled()||!$product->is_taxable())return 0;$rates=WC_Tax::get_rates($product->get_tax_class());return array_sum(array_map(static function($r){return !empty($r['compound'])?0:(float)($r['rate']??0);},$rates))/100;}
 function artwork_render($s){echo '<fieldset class="pov-group pov-artwork"><legend>Grafică</legend><div class="pov-grid"><label class="pov-card"><input type="radio" name="pov_artwork_choice" value="own" checked><span class="pov-card-inner"><span class="pov-card-label">Cu design propriu</span><span class="pov-check">✓</span></span></label><label class="pov-card"><input type="radio" name="pov_artwork_choice" value="service"><span class="pov-card-inner"><span class="pov-card-label">Cu design făcut de noi</span><span class="pov-check">✓</span></span></label></div><div class="pov-upload-panel"><label class="pov-upload-label">↑ Încarcă fișierele de design (PDF / EPS)<input type="file" name="pov_artwork_file" accept=".pdf,.eps,application/pdf,application/postscript"></label><small>Maxim 20 MB. Un singur fișier. Pentru mai multe fișiere, contactează tipografia.</small></div>';
 if($s['templates_pdf']||$s['templates_eps']){echo '<details class="pov-templates"><summary>↓ Descarcă template design</summary><div class="pov-template-links">';foreach(['pdf'=>'PDF','eps'=>'EPS'] as $k=>$label)if(!empty($s['templates_'.$k]))echo '<a href="'.esc_url($s['templates_'.$k]).'" target="_blank" rel="noopener" download>Template '.esc_html($label).'</a>';echo '</div></details>';}echo '</fieldset>';}
 function upload_error($file){if(!is_array($file)||empty($file['name'])||!empty($file['error']))return 'Fișierul de grafică lipsește sau încărcarea a eșuat.';if((int)$file['size']>20*1024*1024)return 'Fișierul depășește limita de 20 MB.';$ext=strtolower(pathinfo($file['name'],PATHINFO_EXTENSION));if(!in_array($ext,['pdf','eps'],true))return 'Sunt acceptate doar fișiere PDF sau EPS.';if(!is_uploaded_file($file['tmp_name']))return 'Fișierul încărcat nu este valid.';$f=fopen($file['tmp_name'],'rb');$sig=$f?fread($f,8):'';if($f)fclose($f);if(($ext==='pdf'&&strncmp($sig,'%PDF-',5)!==0)||($ext==='eps'&&strncmp($sig,'%!PS',4)!==0&&substr($sig,0,4)!=="\xC5\xD0\xD3\xC6"))return 'Conținutul fișierului nu corespunde extensiei.';return '';}
 function cart_item_name($name,$item,$key){return $name;}
 function parse_tiers($text){$tiers=[];foreach(preg_split('/\r?\n/',(string)$text) as $line)if(preg_match('/^(\d+)=(\d+(?:\.\d+)?)$/',trim($line),$m))$tiers[(int)$m[1]]=(float)$m[2];ksort($tiers,SORT_NUMERIC);return $tiers;}
 function selections($id){$groups=$this->groups($id);$raw=isset($_POST['pov'])&&is_array($_POST['pov'])?wp_unslash($_POST['pov']):[];$out=[];$valid=true;foreach($groups as $i=>$g){$values=isset($raw[$i])?(array)$raw[$i]:[];if(!$values&&!empty($g['required'])){$valid=false;continue;}if(empty($g['multiple'])&&count($values)>1){$valid=false;continue;}$chosen=[];foreach($values as $v){if(!is_scalar($v)||!ctype_digit((string)$v)||!isset($g['options'][(int)$v])){$valid=false;continue;}$chosen[(int)$v]=$g['options'][(int)$v];}if($chosen)$out[]=['title'=>$g['title'],'options'=>array_values($chosen)];}return [$valid,$out];}
 function validate($passed,$id,$qty,$variation_id=0,$variations=[]){if(!$this->valid_qty($id,$qty)){wc_add_notice('Cantitatea trebuie să respecte minimul și pasul de comandă configurate.','error');return false;}if(!empty($this->settings($id)['artwork'])){$choice=sanitize_key(wp_unslash($_POST['pov_artwork_choice']??''));if(!in_array($choice,['own','service'],true)){wc_add_notice('Alege tipul de grafică.','error');return false;}if($choice==='own'&&!empty($this->settings($id)['upload_required'])){$err=$this->upload_error($_FILES['pov_artwork_file']??null);if($err){wc_add_notice($err,'error');return false;}}else if($choice==='own'&&!empty($_FILES['pov_artwork_file']['name'])){$err=$this->upload_error($_FILES['pov_artwork_file']);if($err){wc_add_notice($err,'error');return false;}}}if($this->groups($id)){[$valid]=$this->selections($id);if(!$valid){wc_add_notice('Te rugăm să selectezi opțiunile valide și obligatorii.','error');return false;}}return $passed;}
 function cart_qty_validation($passed,$key,$values,$qty){$id=$values['product_id']??0;if(!$this->valid_qty($id,$qty)){wc_add_notice('Cantitatea selectată nu respectă minimul și multiplicatorul produsului.','error');return false;}return $passed;}
 function cart_data($data,$id,$variation_id){if($variation_id)return $data;[$valid,$selected]=$this->selections($id);if(!$valid)return $data;$s=$this->settings($id);if(!$selected&&$s['mode']==='fixed'&&$s['min']===1&&$s['step']===1&&!$s['artwork'])return $data;$unit=0;$order=0;foreach($selected as $g)foreach($g['options'] as $o){if(($o['charge']??'unit')==='order')$order+=(float)$o['price'];else $unit+=(float)$o['price'];}if(!empty($s['artwork'])){$choice=sanitize_key(wp_unslash($_POST['pov_artwork_choice']??'own'));$data['pov_artwork_choice']=$choice==='service'?'Cu design făcut de noi':'Cu design propriu';if($choice==='service')$order+=(float)$s['design_fee'];if($choice==='own'&&!empty($_FILES['pov_artwork_file']['name'])&&!$this->upload_error($_FILES['pov_artwork_file'])){require_once ABSPATH.'wp-admin/includes/file.php';$uploaded=wp_handle_upload($_FILES['pov_artwork_file'],['test_form'=>false,'mimes'=>['pdf'=>'application/pdf','eps'=>'application/postscript']]);if(!empty($uploaded['file'])&&!empty($uploaded['url'])){$data['pov_artwork_url']=esc_url_raw($uploaded['url']);$data['pov_artwork_name']=sanitize_file_name(wp_basename($uploaded['file']));}else{wc_add_notice('Încărcarea fișierului de grafică a eșuat.','error');}}}$data['pov_original_base']=(float)wc_get_product($id)->get_price('edit');$data['pov_selection']=$selected;$data['pov_unit_extra']=$unit;$data['pov_order_extra']=$order;$data['pov_mode']=$s['mode'];$data['pov_tiers']=$this->parse_tiers($s['tiers']);$data['pov_unique']=md5(wp_json_encode($selected).$s['mode'].wp_json_encode($data['pov_tiers']).($data['pov_artwork_url']??'').($data['pov_artwork_choice']??''));return $data;}
 function item_data($data,$cart_item){foreach(($cart_item['pov_selection']??[]) as $g)$data[]=['key'=>$g['title'],'value'=>implode(', ',array_map(static fn($o)=>$o['label'],$g['options']))];if(!empty($cart_item['pov_artwork_choice']))$data[]=['key'=>'Grafică','value'=>$cart_item['pov_artwork_choice']];if(!empty($cart_item['pov_artwork_url']))$data[]=['key'=>'Fișier grafică','value'=>esc_url($cart_item['pov_artwork_url']),'display'=>'<a href="'.esc_url($cart_item['pov_artwork_url']).'" target="_blank" rel="noopener">'.esc_html($cart_item['pov_artwork_name']??'Descarcă fișier').'</a>'];return $data;}
 function price($cart){if(is_admin()&&!wp_doing_ajax())return;if(!$cart)return;foreach($cart->get_cart() as $key=>$item){if(!isset($item['pov_mode']))continue;$p=$item['data'];$qty=max(1,(int)$item['quantity']);$base=isset($item['pov_original_base'])?(float)$item['pov_original_base']:(float)wc_get_product($item['product_id'])->get_price('edit');$tiers=$item['pov_tiers']??[];if($item['pov_mode']==='dynamic'&&$tiers){foreach($tiers as $threshold=>$total){if($qty>=(int)$threshold)$base=(float)$total/(int)$threshold;else break;}}$p->set_price(max(0,$base+(float)$item['pov_unit_extra']+(float)$item['pov_order_extra']/$qty));}}
 function order_item($item,$key,$values,$order){foreach(($values['pov_selection']??[]) as $g)$item->add_meta_data($g['title'],implode(', ',array_map(static fn($o)=>$o['label'],$g['options'])),true);if(!empty($values['pov_artwork_choice']))$item->add_meta_data('Grafică',$values['pov_artwork_choice'],true);if(!empty($values['pov_artwork_url']))$item->add_meta_data('Fișier grafică',esc_url_raw($values['pov_artwork_url']),true);}
 function needs_configurator($id){$s=$this->settings($id);return (bool)$this->groups($id)||$s['mode']!=='fixed'||(int)$s['min']!==1||(int)$s['step']!==1||!empty($s['artwork']);}
 function quote_enabled($id){$s=$this->settings($id);return !empty($s['quote']);}
 function quote_button_html($id,$label='Cere ofertă'){$url=POV_Quote::button_url((int)$id);return '<div class="pov-quote-cta"><a class="pov-quote-btn" href="'.esc_url($url).'">'.POV_Quote::button_icon().'<span>'.esc_html($label).'</span></a></div>';}
 function quote_button(){global $product;if(!$product instanceof WC_Product)return;$id=(int)$product->get_id();if(isset($this->quote_printed[$id]))return;if(!$this->quote_enabled($id))return;$this->quote_printed[$id]=true;echo $this->quote_button_html($id);}
 function quote_shortcode($atts=[]){$args=shortcode_atts(['id'=>0,'label'=>'Cere ofertă','force'=>0],is_array($atts)?$atts:[],'pov_quote_button');$id=absint($args['id']);if(!$id){global $product;if($product instanceof WC_Product)$id=(int)$product->get_id();}if(!$id)$id=(int)get_the_ID();if(!$id)return '';$force=!empty($args['force']);if(!$force&&!$this->quote_enabled($id))return '';if(isset($this->quote_printed[$id]))return '';$this->quote_printed[$id]=true;return $this->quote_button_html($id,sanitize_text_field($args['label']));}
 function quote_content_fallback($content){if(!is_singular('product'))return $content;global $product;if(!$product instanceof WC_Product)return $content;$id=(int)$product->get_id();if(isset($this->quote_printed[$id])||!$this->quote_enabled($id))return $content;if($product->is_purchasable()&&''!==(string)$product->get_price('edit'))return $content;$this->quote_printed[$id]=true;return $content.$this->quote_button_html($id);}
 function frontend_assets(){if(!is_product())return;global $post;if(!$post)return;$config=$this->needs_configurator($post->ID);$quote=$this->quote_enabled($post->ID);if(!$config&&!$quote)return;wp_enqueue_style('pov-front',plugins_url('assets/front.css',__FILE__),[],self::VERSION);if(!$config)return;wp_enqueue_script('pov-front',plugins_url('assets/front.js',__FILE__),[],self::VERSION,true);wp_localize_script('pov-front','povConfig',['locale'=>str_replace('_','-',get_locale()),'currency'=>get_woocommerce_currency(),'decimals'=>wc_get_price_decimals()]);}
}
